"""Explain scatterlists and public KMSAN marking hooks in beginner Korean."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1821': ('택배 한 건에 상자가 여러 개 있을 수 있어요. 메모리의 여러 조각도 목록에 적어 하나씩 처리할 수 있어요.', '떨어져 있는 메모리 조각을 목록 순서대로 처리하는 방법을 이해합니다.', '종이에 A, B, C를 쓰고 방문 순서를 A→C로 정하세요. 두 항목을 처리한다면 B도 방문하는지 말해 보세요.', ['메모리는 데이터를 담는 공간이에요. scatter-gather 목록은 여러 곳에 흩어진 메모리 조각을 나타내요. 긴 데이터를 꼭 한 덩어리로 모으지 않아도 각 조각의 위치와 길이를 알려 줄 수 있어요.', '항목 하나에는 페이지, 그 페이지 안에서 시작할 위치인 offset, 처리할 길이인 length가 있어요. 페이지는 메모리를 일정 크기로 나눈 구역이에요. 100번째 바이트부터 20바이트를 처리한다면 시작 위치는 100, 길이는 20이에요.', 'kmsan_handle_dma_sg는 이 목록을 받아요. KMSAN은 아직 준비되지 않은 값을 사용하는 실수를 찾는 검사 도구예요. DMA는 장치와 메모리 사이의 데이터 이동을 지원하는 방식이고, 여기서는 그 이동 방향에 맞는 검사 처리를 요청해요.', 'for_each_sg는 목록의 항목을 차례대로 방문하는 도우미예요. nents는 방문할 항목 수이고 item은 지금 보고 있는 항목이에요. 각 항목에서 sg_page(item), item->offset, item->length를 꺼내 kmsan_handle_dma에 전달해요. dir는 전송 방향이며 각 호출에 함께 전달해요.', '목록을 방문하는 규칙은 단순히 메모리의 바로 다음 칸으로 이동하는 것과 같다고 단정할 수 없어요. 실제 scatterlist에는 목록을 잇는 규칙이 있고 for_each_sg가 그 규칙을 따라요. 항목마다 시작 위치와 길이도 다를 수 있어요.', '종이 모형에서 A→C라는 방문 순서와 항목 수 2를 정하면 A와 C를 처리하고 B는 건너뛰어요. 이는 방문 순서를 이해하는 모형이에요. 실제 Linux 구조체에 평범한 next 칸이 있다고 주장하거나 실제 목록 연결 방식을 그대로 재현한 것은 아니에요.'], [('목록의 항목 하나를 처리할 때 어떤 정보를 넘기나요?', ['언제나 첫 항목의 페이지와 길이만 넘겨요', '현재 항목의 페이지·시작 위치·길이와 전송 방향을 넘겨요'], '정답은 두 번째예요. 상자마다 주소와 크기가 다르듯 메모리 조각도 위치와 길이가 달라요. 코드에서 item은 현재 항목을 뜻하므로 언제나 첫 항목의 정보를 쓰는 것은 아니에요.'), ('종이 모형의 방문 순서가 A→C이고 두 항목을 처리한다면 B도 처리하나요?', ['아니요. 정해진 순서에 있는 A와 C만 처리해요', '네. 종이에서 가운데 있는 B도 반드시 처리해요'], '정답은 첫 번째예요. 방문 순서와 개수가 기준이에요. 종이에서 가까이 놓여 있다는 이유로 B를 추가하지 않아요. 실제 Linux의 연결 표현은 이 종이 모형보다 복잡해요.')]), 'os1822': ('검사원이 일하는 도중에 같은 검사 일을 또 시작하면 서로 기다리다가 일이 멈출 수 있어요. 그래서 들어가기 전에 확인해요.', '미준비 표시를 붙이는 함수가 검사 도구 내부에서는 돌아가는 이유를 이해합니다.', '입구에 검사 꺼짐 또는 검사 도구 내부라는 두 조건을 쓰고, 하나라도 맞으면 돌아가는 화살표를 그리세요.', ['KMSAN은 메모리 값이 사용해도 되는 상태인지 별도의 검사표로 추적해요. poison은 이 검사표에 아직 준비되지 않았다는 표시를 붙이는 일이에요. 실제 데이터에 독을 넣거나 특정 숫자를 써 넣는다는 뜻은 아니에요.', 'kmsan_poison_memory의 address는 표시할 곳의 주소이고 size는 길이예요. flags는 내부 작업에 전달할 메모리 할당 조건이에요. 함수는 먼저 kmsan_enabled와 kmsan_in_runtime을 살펴요.', '검사가 꺼져 있거나 이미 KMSAN 내부 작업 중이면 바로 돌아가요. 조건식의 !는 아니다, ||는 둘 중 하나라도라는 뜻이에요. 따라서 두 조건이 모두 맞아야 돌아가는 것이 아니에요.', '미준비 표시에는 어디서 생겼는지 알려 주는 origin 기록도 필요할 수 있어요. 이 기록을 만들 때 함수 호출 경로를 거슬러 모으고 stack depot이라는 보관소에 저장해요. 작업에 필요한 메모리를 얻거나 잠금을 다루다가 이미 진행 중인 검사 작업과 얽힐 수 있어요.', '잠금은 한 번에 한 작업만 들어오게 하는 문과 비슷해요. 문을 잡은 작업이 다시 같은 문이 열리기를 기다리면 더 진행하지 못할 수 있어요. 이를 교착 상태라고 해요. 원문 주석은 검사 도구 내부에서 origin 기록을 만들 때 이런 위험이 있어 돌아간다고 설명해요.', '통과하면 enter_runtime으로 내부 작업 시작을 표시하고, 내부 poison 함수에 KMSAN_POISON_NOCHECK를 전달한 뒤 leave_runtime으로 끝을 표시해요. NOCHECK는 이 호출의 검사 옵션 이름이에요. 메모리를 해제했다는 FREE 표시와 다르며, 잘못된 주소를 아무렇게나 넣어도 된다는 허락은 아니에요.'], [('이미 KMSAN 내부 작업 중일 때 이 함수가 돌아가는 이유는 무엇인가요?', ['미준비 표시는 언제나 숫자 하나를 쓰는 간단한 일이라서요', '발생 위치 기록을 만드는 일이 내부 작업과 얽혀 멈출 수 있어서요'], '정답은 두 번째예요. 호출 경로를 모아 보관하는 일에는 추가 작업이 필요해요. 단순한 숫자 대입이라고 생각하면 잠금이나 메모리 할당 때문에 생기는 위험을 놓쳐요.'), ('이 함수가 내부 poison 함수에 넘기는 표시 옵션은 무엇인가요?', ['KMSAN_POISON_NOCHECK예요', '언제나 KMSAN_POISON_FREE예요'], '정답은 첫 번째예요. 호출문의 마지막 인자를 보면 NOCHECK라고 적혀 있어요. 이 함수는 지정한 범위를 미준비로 표시하며, 반드시 메모리 해제를 뜻하는 FREE를 넘기지는 않아요.')]), 'os1823': ('공책 내용을 새로 쓰는 일과 검사표에 확인 표시를 하는 일은 달라요. 준비됨 표시를 붙여도 공책의 내용 자체는 바뀌지 않아요.', '준비됨 표시와 실제 데이터 쓰기를 구별하고 두 공개 함수의 입구 조건을 비교합니다.', '값이 7인 칸과 미준비 검사표를 따로 그리세요. unpoison 뒤 값은 7 그대로, 검사표만 준비됨으로 바꾸세요.', ['kmsan_unpoison_memory는 지정한 메모리 범위를 준비됨 상태로 추적하도록 검사 정보를 바꿔요. 실제 내용과 검사 정보는 서로 다른 것이에요. 검사표만 바꿔서는 원래 쓰지 않았던 값이 자동으로 채워지지 않아요.', 'address는 표시할 범위의 시작 주소이고 size는 바이트 수예요. 바이트는 메모리 크기를 세는 단위예요. size가 8이면 지정한 시작점부터 8바이트에 해당하는 검사 정보를 다뤄요.', '입구에서는 kmsan_enabled가 꺼졌는지만 확인해요. poison 함수에 있던 kmsan_in_runtime 조건은 여기 없어요. 따라서 이미 검사 도구 내부 작업 중이라는 이유만으로 무조건 돌아가지는 않아요.', '왜 차이가 날까요? 원문 주석은 이 unpoison 경로가 메모리 할당을 일으키거나 검사 코드가 삽입된 코드를 호출하지 않는다고 설명해요. poison에서 발생 위치 기록을 새로 만드는 작업과 조건이 달라 내부에서도 사용할 수 있어요.', '먼저 user_access_save로 사용자 메모리 접근과 관련된 상태를 보관하고, 내부 unpoison 함수를 호출한 뒤 user_access_restore로 보관한 상태를 복구해요. 출입문 설정을 잠시 다룬 뒤 원래 설정으로 돌려놓는 것처럼, 이전 상태를 잃지 않도록 한 쌍으로 읽어요.', '내부 함수에는 KMSAN_POISON_NOCHECK 옵션을 넘겨요. 이 본문에는 poison과 같은 enter_runtime·leave_runtime 호출이 없어요. 이름이 비슷한 두 함수라도 입구 조건과 실제 호출 순서를 따로 확인해야 해요.'], [('KMSAN이 켜져 있고 이미 내부 작업 중이면 공개 unpoison은 반드시 생략되나요?', ['네. poison과 똑같이 무조건 돌아가요', '아니요. 내부 작업 중이라는 이유만으로 생략하지 않아요'], '정답은 두 번째예요. 이 함수의 조기 반환 조건에는 검사 켜짐 여부만 있어요. poison의 조건을 그대로 복사해 생각하면 두 함수의 차이를 놓쳐요.'), ('unpoison을 호출하면 실제 데이터도 모두 숫자 0이 되나요?', ['아니요. 검사 정보를 준비됨으로 바꾸는 일이에요', '네. 실제 메모리의 모든 값을 0으로 써요'], '정답은 첫 번째예요. 공책에 확인 표시를 붙여도 글씨가 바뀌지 않는 것과 같아요. 실제 값을 0으로 채우는 일은 별도의 데이터 쓰기예요.')]), 'os1824': ('주소가 적힌 쪽지의 크기와 그 주소에 있는 상자의 크기는 달라요. 이 함수는 쪽지가 아니라 상자 전체의 크기를 전달해요.', '포인터의 크기와 포인터가 가리키는 구조체의 크기를 구별합니다.', '가상 예에서 주소 쪽지 8바이트, 상자 32바이트를 그리세요. sizeof(regs)와 sizeof(*regs)를 각각 연결하세요.', ['IRQ는 장치 등이 CPU에 처리를 요청하는 인터럽트를 뜻해요. CPU는 계산을 수행하는 장치이고 레지스터는 CPU 안의 작은 저장 공간이에요. 인터럽트를 처리하는 진입 과정에서는 필요한 레지스터 정보를 메모리에 저장해 두어요.', 'pt_regs는 그런 정보를 담는 구조체 형식이에요. 구조체는 여러 값을 하나로 묶은 상자라고 생각하면 돼요. 어떤 정보가 들어가는지와 전체 크기는 CPU 종류에 따라 달라질 수 있어요.', 'regs는 상자 자체가 아니라 상자의 주소를 나타내는 포인터예요. sizeof(regs)는 포인터의 크기이고 sizeof(*regs)는 가리키는 struct pt_regs의 크기예요. 별표 *가 가리키는 대상이라는 뜻을 만들어 줘요.', '주소를 담는 포인터가 8바이트이고 가상의 구조체가 32바이트라면 sizeof(regs)는 8, sizeof(*regs)는 32예요. 이 숫자는 크기 차이를 배우는 예시이며 실제 모든 CPU의 pt_regs가 32바이트라는 뜻은 아니에요.', 'kmsan_unpoison_entry_regs의 본문은 regs와 sizeof(*regs)를 kmsan_unpoison_memory에 넘겨요. 이미 레지스터 정보가 저장된 영역 전체를 검사표에서 준비됨으로 표시하도록 요청해요. 이 짧은 함수가 CPU 레지스터를 직접 읽어서 저장하는 것은 아니에요.', '여기서 sizeof(*regs)는 구조체 형식의 크기를 구해요. 이 식 때문에 실제 구조체 내용을 읽는 것은 아니에요. 다만 이후 unpoison에 주소를 전달하므로 호출자는 올바른 저장 영역을 제공해야 해요. 크기 계산과 실제 주소 사용을 나누어 생각하세요.'], [('sizeof(*regs)는 무엇의 크기를 구하나요?', ['주소를 담는 포인터 변수 자체의 크기예요', 'regs가 가리키는 구조체 전체의 크기예요'], '정답은 두 번째예요. *regs는 가리키는 대상을 뜻해요. 가상 예에서 포인터 8바이트, 구조체 32바이트라면 이 식의 결과는 32예요. 포인터 크기는 sizeof(regs)로 구해요.'), ('이 함수가 CPU 레지스터를 직접 메모리에 저장하나요?', ['아니요. 저장 영역의 검사 정보를 준비됨으로 바꾸도록 요청해요', '네. 인터럽트 진입의 모든 저장 작업을 직접 수행해요'], '정답은 첫 번째예요. 본문에는 unpoison 호출이 있어요. 실제 레지스터 저장과 그 영역에 준비됨 표시를 붙이는 일은 서로 다른 역할이에요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_451.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
